<script setup lang="ts">import { useRouter,useRoute } from 'vue-router';import { useAuthStore } from '../../stores/auth';const router=useRouter();const route=useRoute();const auth=useAuthStore();const isRegister=()=>route.path==='/register';async function submit(){if(isRegister())await auth.register('demo','demo-password');else await auth.login('demo','demo-password');router.push('/profile')}</script><template><section class="auth-page"><div class="eyebrow">ACCOUNT</div><h1>{{isRegister()?'创建你的档案':'欢迎回来'}}</h1><p class="lede">使用演示账号继续体验智选志愿。</p><button class="primary" @click="submit">继续 ↗</button></section></template>
